record.field:
picking = record

for move in picking.move_ids.filtered(
    lambda m: m.product_id.tracking in ('lot', 'serial')
):
    if not move.show_details_visible:
        raise UserError(
            'Sản phẩm %s yêu cầu Lot/Serial nhưng nút Details không hiển thị trên giao diện.'
            % move.product_id.display_name
        )

    missing_lines = move.move_line_ids.filtered(
        lambda line: line.quantity > 0
        and not line.lot_id
        and not line.lot_name
    )

    for line in missing_lines:
        if move.product_id.tracking == 'serial' and line.quantity != 1:
            raise UserError(
                'Sản phẩm %s theo dõi bằng Serial phải có số lượng mỗi dòng bằng 1.'
                % move.product_id.display_name
            )

        product_code = move.product_id.default_code or str(move.product_id.id)
        lot_name = 'IN-%s-%s-%s' % (
            picking.name.replace('/', '-'),
            product_code,
            line.id,
        )

        lot = env['stock.lot'].create({
            'name': lot_name,
            'product_id': move.product_id.id,
            'company_id': picking.company_id.id,
        })

        line.write({
            'lot_id': lot.id,
        })
